begin;
create table public.arena_alliance_pass_seasons(id text primary key,name text not null,starts_at timestamptz not null,ends_at timestamptz not null,active boolean not null default true);create table public.arena_alliance_pass_rewards(season_id text not null references public.arena_alliance_pass_seasons(id)on delete cascade,level integer not null,requisite_xp integer not null,reward_currency text not null check(reward_currency in('coins','gems')),reward_amount integer not null,premium boolean not null default false,primary key(season_id,level,premium));create table public.arena_alliance_pass_claims(season_id text not null,level integer not null,premium boolean not null,user_id uuid not null references public.profiles(id)on delete cascade,claimed_at timestamptz not null default now(),primary key(season_id,level,premium,user_id),foreign key(season_id,level,premium)references public.arena_alliance_pass_rewards);insert into public.arena_alliance_pass_seasons values('aliancas-s1','Temporada do Reino',date_trunc('month',now()),date_trunc('month',now())+interval'90 days',true);insert into public.arena_alliance_pass_rewards values('aliancas-s1',1,0,'coins',100,false),('aliancas-s1',2,100,'coins',200,false),('aliancas-s1',3,250,'gems',2,false),('aliancas-s1',4,450,'coins',350,false),('aliancas-s1',5,700,'gems',3,false),('aliancas-s1',1,0,'gems',2,true),('aliancas-s1',2,100,'gems',3,true),('aliancas-s1',3,250,'coins',500,true),('aliancas-s1',4,450,'gems',5,true),('aliancas-s1',5,700,'gems',10,true);alter table public.arena_alliance_pass_seasons enable row level security;alter table public.arena_alliance_pass_rewards enable row level security;alter table public.arena_alliance_pass_claims enable row level security;revoke all on public.arena_alliance_pass_seasons,public.arena_alliance_pass_rewards,public.arena_alliance_pass_claims from anon,authenticated;
create or replace function public.arena_get_alliance_pass()returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_xp integer;v_pro boolean;v_season text;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;select id into v_season from public.arena_alliance_pass_seasons where active and now()between starts_at and ends_at order by starts_at desc limit 1;select xp into v_xp from public.arena_alliances where id=v_alliance;v_pro:=public.arena_alliance_has_pro(v_alliance);return jsonb_build_object('season',v_season,'xp',v_xp,'is_pro',v_pro,'rewards',(select jsonb_agg(jsonb_build_object('level',r.level,'xp',r.requisite_xp,'currency',r.reward_currency,'amount',r.reward_amount,'premium',r.premium,'claimed',exists(select 1 from public.arena_alliance_pass_claims c where c.season_id=r.season_id and c.level=r.level and c.premium=r.premium and c.user_id=v_user))order by r.level,r.premium)from public.arena_alliance_pass_rewards r where r.season_id=v_season));end;$$;
create or replace function public.arena_claim_alliance_pass(p_level integer,p_premium boolean)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_xp integer;v_pro boolean;v_reward public.arena_alliance_pass_rewards%rowtype;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;select xp into v_xp from public.arena_alliances where id=v_alliance;v_pro:=public.arena_alliance_has_pro(v_alliance);select r.*into v_reward from public.arena_alliance_pass_rewards r join public.arena_alliance_pass_seasons s on s.id=r.season_id where s.active and now()between s.starts_at and s.ends_at and r.level=p_level and r.premium=p_premium;if not found or v_xp<v_reward.requisite_xp or(p_premium and not v_pro)then raise exception'reward locked';end if;insert into public.arena_alliance_pass_claims values(v_reward.season_id,v_reward.level,v_reward.premium,v_user,now());insert into public.arena_player_wallets(user_id)values(v_user)on conflict do nothing;if v_reward.reward_currency='gems'then update public.arena_player_wallets set gems=gems+v_reward.reward_amount where user_id=v_user;else update public.arena_player_wallets set coins=coins+v_reward.reward_amount where user_id=v_user;end if;insert into public.arena_wallet_transactions(user_id,currency,amount,transaction_type,source,reference_id,idempotency_key)values(v_user,v_reward.reward_currency,v_reward.reward_amount,'earn','alliance-pass',v_reward.season_id||':'||v_reward.level,'alliance-pass:'||v_reward.season_id||':'||v_reward.level||':'||p_premium||':'||v_user);return jsonb_build_object('claimed',true);exception when unique_violation then raise exception'already claimed';end;$$;
revoke all on function public.arena_get_alliance_pass(),public.arena_claim_alliance_pass(integer,boolean)from public;grant execute on function public.arena_get_alliance_pass(),public.arena_claim_alliance_pass(integer,boolean)to authenticated;commit;
